() => {
  // Try to find search result containers
  const results = document.querySelectorAll('.result, .c-container, .search-result, [class*="result"], h3 a');
  const items = [];

  // Try h3 headings which typically contain search result titles
  const h3Links = document.querySelectorAll('h3 a, h3.t a');
  h3Links.forEach((a, i) => {
    if (i < 3) {
      items.push({
        title: a.textContent.trim(),
        url: a.href
      });
    }
  });

  // If that didn't work, try other selectors
  if (items.length === 0) {
    const allLinks = document.querySelectorAll('a');
    allLinks.forEach((a, i) => {
      if (i < 30 && a.textContent.trim() && a.href && !a.href.includes('javascript') && a.offsetParent !== null) {
        items.push({
          title: a.textContent.trim(),
          url: a.href
        });
      }
    });
  }

  return JSON.stringify(items, null, 2);
}
